example.code:
// The example shows the style properties that can be applied to axis label's text.
Axis axis = new Axis();
axis.LabelStyle.Color = "Red";
axis.LabelStyle.FontFamily = "Times New Roman";
axis.LabelStyle.FontSize = "12pt";
axis.LabelStyle.FontStyle = "Normal";
axis.LabelStyle.FontWeight = "Medium";
axis.LabelStyle.PaddingBottom = "2pt";
axis.LabelStyle.PaddingLeft = "2pt";
axis.LabelStyle.PaddingRight = "2pt";
axis.LabelStyle.PaddingTop = "2pt";
axis.LabelStyle.TextDecoration = "Underline";
axis.LabelStyle.WritingMode = "lr-tb";

// The example shows the style properties that can be applied to axis lines.
Axis axis = new Axis();
axis.LineStyle.BorderColor.Default = "Red";
axis.LineStyle.BorderStyle.Default = "Solid";
axis.LineStyle.BorderWidth.Default = "2pt";

// The example shows the style properties that can be applied to axis major grid lines.
Axis axis = new Axis();
axis.MajorGridStyle.BorderColor.Default = "Gray";
axis.MajorGridStyle.BorderStyle.Default = "Solid";
axis.MajorGridStyle.BorderWidth.Default = "2pt";

// The example shows the style properties that can be applied to axis major tick lines.
Axis axis = new Axis();
axis.MajorTickStyle.BorderColor.Default = "Gray";
axis.MajorTickStyle.BorderStyle.Default = "Solid";
axis.MajorTickStyle.BorderWidth.Default = "2pt";

// The example shows the style properties that can be applied to axis minor grid lines.
Axis axis = new Axis();
axis.MinorGridStyle.BorderColor.Default = "Gray";
axis.MinorGridStyle.BorderStyle.Default = "Solid";
axis.MinorGridStyle.BorderWidth.Default = "2pt";

// The example shows the style properties that can be applied to axis minor tick lines.
Axis axis = new Axis();
axis.MinorTickStyle.BorderColor.Default = "Gray";
axis.MinorTickStyle.BorderStyle.Default = "Solid";
axis.MinorTickStyle.BorderWidth.Default = "2pt";

Plot plot1 = new Plot();
plot1.Name = "Plot1";
Plot plot2 = new Plot();
plot2.Name = "Plot2";
Axis axis = new Axis();
axis.Plots.AddRange([ plot1.Name, plot2.Name ]);

// The example shows the style properties that can be applied to axis title text.
Axis axis = new Axis();
axis.TitleStyle.Color = "Red";
axis.TitleStyle.FontFamily = "Times New Roman";
axis.TitleStyle.FontSize = "12pt";
axis.TitleStyle.FontStyle = "Normal";
axis.TitleStyle.FontWeight = "Medium";
axis.TitleStyle.PaddingBottom = "2pt";
axis.TitleStyle.PaddingLeft = "2pt";
axis.TitleStyle.PaddingRight = "2pt";
axis.TitleStyle.PaddingTop = "2pt";
axis.TitleStyle.TextDecoration = "Underline";

Chart chart = new Chart();
chart.Palette = ChartPalette.Custom;
chart.CustomPalette.Add(ExpressionInfo.FromString("Red"));
chart.CustomPalette.Add(ExpressionInfo.FromString("Blue"));

DataLabel label = new DataLabel();
label.ConnectingLineStyle.Color = "Red";
label.ConnectingLineStyle.Style = "Solid";
label.ConnectingLineStyle.Width = "2pt";

// The example shows the style properties that can be applied to label text.
DataLabel label = new DataLabel();
label.Style.BackgroundColor = "Grey";
label.Style.BorderColor.Default = "Red";
label.Style.BorderStyle.Default = "Solid";
label.Style.BorderWidth.Default = "2pt";
label.Style.Color = "Blue";
label.Style.Format = "f";
label.Style.FontFamily = "Times New Roman";
label.Style.FontSize = "12pt";
label.Style.FontStyle = "Normal";
label.Style.FontWeight = "Medium";
label.Style.TextDecoration = "Underline";

DataSeries series = new DataSeries();
series.Label.Value = ExpressionInfo.FromString("=Sum(Fields!DataField.Value)");
series.Label.TextPosition = TextPosition.Center;
series.Label.Style.Format = "f";

DataSeries series = new DataSeries();
series.ToolTip.Value = ExpressionInfo.FromString("=Sum(Fields!DataField.Value)");
series.ToolTip.Format = "f";

DataSeries series = new DataSeries();
series.Marker.Visible = true;
series.Marker.Shape = MarkerShape.Dot;
series.Marker.Opacity = 0.5d;

// The example shows the style properties that can be applied to data series layout.
DataSeries series = new DataSeries();
series.Style.BackgroundColor = "Grey";
series.Style.BorderColor.Default = "Red";
series.Style.BorderStyle.Default = "Solid";
series.Style.BorderWidth.Default = "2pt";

// The example shows the style properties that can be applied to header or footer.
HeaderFooterOption header = new HeaderFooterOption();
header.Style.BackgroundColor = "Grey";
header.Style.BorderColor.Default = "Red";
header.Style.BorderStyle.Default = "Solid";
header.Style.BorderWidth.Default = "2pt";
header.Style.Color = "Red";
header.Style.FontFamily = "Times New Roman";
header.Style.FontSize = "12pt";
header.Style.FontStyle = "Normal";
header.Style.FontWeight = "Medium";
header.Style.PaddingBottom = "2pt";
header.Style.PaddingLeft = "2pt";
header.Style.PaddingRight = "2pt";
header.Style.PaddingTop = "2pt";
header.Style.TextDecoration = "Underline";

// The example shows the style properties that can be applied to legend series region.
var legendSeries = new LegendSeries();
legendSeries.Style.BackgroundColor = "Grey";
legendSeries.Style.BorderColor.Default = "Red";
legendSeries.Style.BorderStyle.Default = "Solid";
legendSeries.Style.BorderWidth.Default = "2pt";
legendSeries.Style.PaddingBottom = "2pt";
legendSeries.Style.PaddingLeft = "2pt";
legendSeries.Style.PaddingRight = "2pt";
legendSeries.Style.PaddingTop = "2pt";

// The example shows the style properties that can be applied to legend items text.
var legendSeries = new LegendSeries();
legendSeries.TextStyle.Color = "Red";
legendSeries.TextStyle.FontFamily = "Times New Roman";
legendSeries.TextStyle.FontSize = "12pt";
legendSeries.TextStyle.FontStyle = "Normal";
legendSeries.TextStyle.FontWeight = "Medium";
legendSeries.TextStyle.TextDecoration = "Underline";

// The example shows the style properties that can be applied to legend series title text.
var legendSeries = new LegendSeries();
legendSeries.TitleStyle.Color = "Red";
legendSeries.TitleStyle.FontFamily = "Times New Roman";
legendSeries.TitleStyle.FontSize = "12pt";
legendSeries.TitleStyle.FontStyle = "Normal";
legendSeries.TitleStyle.FontWeight = "Medium";
legendSeries.TitleStyle.TextDecoration = "Underline";

SizeLegendSeries legend = new SizeLegendSeries();
legend.RangeOptions.Add(new LegendRangeOption() { To = 5, Title = "0-5" });
legend.RangeOptions.Add(new LegendRangeOption() { To = 10, Title = "5-10" });

// The example shows the style properties that can be applied to marker.
Marker marker = new Marker();
marker.Style.BackgroundColor = "Grey";
marker.Style.BorderColor.Default = "Red";
marker.Style.BorderStyle.Default = "Solid";
marker.Style.BorderWidth.Default = "2pt";

// The example shows the style properties that can be applied to overlays.
Overlay overlay = new Overlay();
overlay.Style.BorderColor.Default = "Red";
overlay.Style.BorderStyle.Default = "Solid";
overlay.Style.BorderWidth.Default = "2pt";

Plot plot = new Plot();

DataSeries series = new DataSeries();
series.Name = "Data Field (Sum)";
series.Values.Add(new DataValue { Caption = "Data Field", Value = ExpressionInfo.FromString("=Fields!DataField.Value") });
plot.DataSeries.Add(series);

Overlay overlay = new Overlay();
overlay.Type = OverlayType.ReferenceLine;
overlay.Field = "Data Field (Sum)"
plot.Config.Overlays.Add(overlay);

Overlay overlay = new Overlay();
overlay.Type = OverlayType.ReferenceLine;
overlay.Field = "Data Field (Sum)"
overlay.LegendLabel = ExpressionInfo.FromString("=Fields!DataField.Value");

// The example shows the style properties that can be applied to pointer.
Pointer pointer = new Pointer();
pointer.Style.BackgroundColor = "Grey";

// The example shows the style properties that can be applied to custom label text.
CustomLabel label = new CustomLabel();
label.Style.Color = "Red";
label.Style.FontFamily = "Times New Roman";
label.Style.FontSize = "12pt";
label.Style.FontStyle = "Normal";
label.Style.FontWeight = "Medium";
label.Style.TextDecoration = "Underline";
label.Style.WritingMode = "lr-tb";

SeriesGrouping grouping = new SeriesGrouping();
grouping.Grouping.GroupExpressions.Add(ExpressionInfo.FromString("=Fields!GroupByField.Value"));

Plot plot = new Plot();
plot.SeriesGroupings.Add(grouping);

CategoryGrouping grouping = new CategoryGrouping();
grouping.Grouping.GroupExpressions.Add(ExpressionInfo.FromString("=Fields!GroupByField.Value"));

Plot plot = new Plot();
plot.CategoryGroupings.Add(grouping);

DataSeries series = new DataSeries();
series.Values.Add(new DataValue { Caption = "Data Field", Value = ExpressionInfo.FromString("=Fields!DataField.Value") });

Plot plot = new Plot();
plot.DataSeries.Add(series);

Plot plot = new Plot();
plot.Type = PlotType.Bar;
plot.ColorSeries.Field = ExpressionInfo.FromString("=Fields!GroupByField.Value");
plot.ColorSeries.Position = Position.Top;

Plot plot = new Plot();
plot.Type = PlotType.Line;
plot.SizeSeries.Field = ExpressionInfo.FromString("=Fields!GroupByField.Value");
plot.SizeSeries.RangeOptions.Add(new LegendRangeOption() { To = 5, Title = "0-5" });
plot.SizeSeries.RangeOptions.Add(new LegendRangeOption() { To = 10, Title = "5-10" });

Plot plot = new Plot();
plot.Type = PlotType.Scatter;
plot.ShapeSeries.Field = ExpressionInfo.FromString("=Fields!GroupByField.Value");
plot.ColorSeries.Position = Position.Top;

Plot plot = new Plot();
plot.Config.Axes.Add(new Axis() { Title = "Axis1", Format = "f" });
plot.Config.Style.BackgroundColor = "LightGray";

// The example shows the style properties that can be applied to plot area.
PlotArea plotArea = new PlotArea();
plotArea.Style.BackgroundColor = "LightGray";
plotArea.Style.BorderColor.Default = "Red";
plotArea.Style.BorderStyle.Default = "Solid";
plotArea.Style.BorderWidth.Default = "2pt";
plotArea.Style.PaddingBottom = "2pt";
plotArea.Style.PaddingLeft = "2pt";
plotArea.Style.PaddingRight = "2pt";
plotArea.Style.PaddingTop = "2pt";

Plot plot = new Plot();
plot.BarLineStyle.Color = "Red";
plot.BarLineStyle.Style = "Solid";
plot.BarLineStyle.Width = "2pt";

Plot plot = new Plot();

DataSeries series = new DataSeries();
series.Name = "Data Field (Sum)";
series.Values.Add(new DataValue { Caption = "Data Field", Value = ExpressionInfo.FromString("=Fields!DataField.Value") });
plot.DataSeries.Add(series);

Overlay overlay = new Overlay();
overlay.Type = OverlayType.ReferenceLine;
overlay.Field = "Data Field (Sum)"
plot.Config.Overlays.Add(overlay);

Plot plot = new Plot();
plot.Type = PlotType.Gauge;

DataSeries series = new DataSeries();
series.Name = "Data Field (Sum)";
series.Values.Add(new DataValue { Caption = "Data Field", Value = ExpressionInfo.FromString("=Fields!DataField.Value") });
plot.DataSeries.Add(series);

plot.Config.Pointers.Add( new Pointer() { End = ExpressionInfo.FromString("500") } );

Plot plot = new Plot();
plot.Type = PlotType.Gauge;

DataSeries series = new DataSeries();
series.Name = "Data Field (Sum)";
series.Values.Add(new DataValue { Caption = "Data Field", Value = ExpressionInfo.FromString("=Fields!DataField.Value") });
plot.DataSeries.Add(series);

plot.Config.CustomLabels.Add( new CustomLabel() { Text = ExpressionInfo.FromString("Data:") } );
plot.Config.CustomLabels.Add( new CustomLabel() { Text = ExpressionInfo.FromString("=Fields!DataField.Value"), OffsetY = "1in" } );
